def solution(input_str):
    """
    Solve the binary tree construction problem with constraints.

    The approach:
    1. Parse n and c from input
    2. Build ordering constraints from LEFT/RIGHT constraints
    3. Check for cycles in ordering (impossible case)
    4. Do topological sort to get valid inorder traversal
    5. Output the result
    """

    lines = input_str.strip().split('\n')
    if not lines:
        return "IMPOSSIBLE\n"

    n, c = map(int, lines[0].split())

    if n == 1:
        return "1\n"

    constraints = []
    for i in range(1, min(c + 1, len(lines))):
        if i >= len(lines):
            break
        parts = lines[i].split()
        ai, bi = int(parts[0]), int(parts[1])
        # direction is parts[2]
        direction = parts[2] if len(parts) > 2 else ""
        constraints.append((ai, bi, direction))

    # Build order constraints: u -> v means u comes before v in inorder
    before = []

    for ai, bi, direction in constraints:
        if direction == "LEFT":
            before.append((bi, ai))  # bi before ai in inorder
        elif direction == "RIGHT":
            before.append((ai, bi))  # ai before bi in inorder

    # Check for cycles using DFS
    adj = {}
    for i in range(1, n + 1):
        adj[i] = []
    for u, v in before:
        if v not in adj[u]:
            adj[u].append(v)

    visited = set()
    rec_stack = set()

    def dfs(node):
        visited.add(node)
        rec_stack.add(node)
        for neighbor in adj[node]:
            if neighbor not in visited:
                if dfs(neighbor):
                    return True
            elif neighbor in rec_stack:
                return True
        rec_stack.remove(node)
        return False

    for node in range(1, n + 1):
        if node not in visited:
            if dfs(node):
                return "IMPOSSIBLE\n"

    # Topological sort (Kahn's algorithm)
    in_degree = {i: 0 for i in range(1, n + 1)}
    for u in adj:
        for v in adj[u]:
            in_degree[v] += 1

    queue = [i for i in range(1, n + 1) if in_degree[i] == 0]
    queue.sort()

    result = []
    while queue:
        node = queue.pop(0)
        result.append(node)
        for neighbor in adj[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)
                queue.sort()

    if len(result) != n:
        return "IMPOSSIBLE\n"

    return " ".join(map(str, result)) + " \n"

