def solution(input_str):
    # Parse input
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    # Read the grid
    grid = []
    for i in range(1, len(lines)):
        grid.append(list(lines[i]))

    # Verify grid dimensions
    if len(grid) != n:
        return '0'
    for row in grid:
        if len(row) != m:
            return '0'

    # Convert to integers
    # '0' -> 0 (unpainted), '1'-'4' -> 1-4
    nums = []
    for r in range(n):
        nums.append([int(ch) if ch != '0' else 0 for ch in grid[r]])

    # Check if pre-filled values have conflicts
    def are_adjacent(r1, c1, r2, c2):
        dr = abs(r1 - r2)
        dc = abs(c1 - c2)
        return dr <= 1 and dc <= 1 and (dr, dc) != (0, 0)

    def has_conflict(nums):
        for r in range(n):
            for c in range(m):
                if nums[r][c] == 0:
                    continue
                for dr in range(-1, 2):
                    for dc in range(-1, 2):
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < m:
                            if nums[nr][nc] != 0 and nums[nr][nc] == nums[r][c]:
                                return True
        return False

    if has_conflict(nums):
        return '0'

    # Try to find a coloring using backtracking
    def can_color(r, c, color):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m:
                    if nums[nr][nc] != 0 and nums[nr][nc] == color:
                        return False
        return True

    def backtrack(idx):
        if idx == n * m:
            return True

        r, c = idx // m, idx % m

        if nums[r][c] != 0:
            return backtrack(idx + 1)

        for color in range(1, 5):
            if can_color(r, c, color):
                nums[r][c] = color
                if backtrack(idx + 1):
                    return True
                nums[r][c] = 0

        return False

    if backtrack(0):
        # Format output
        output_lines = []
        for r in range(n):
            output_lines.append(''.join(str(x) for x in nums[r]))
        return '\n'.join(output_lines)
    else:
        return '0'


