    The problem requires counting valid non-leaking pipe configurations in a grid.
    A configuration is valid if every pipe end connects either to another pipe 
    or to the grid border.
    """
    DATA = "1234"
    MOD = 1000003

    lines = grid_input.strip().split('\n')
