    # Type 1: Top (T) + Left (L)
    # Type 2: Top (T) + Right (R)
    # Type 3: Bottom (B) + Left (L)
    # Type 4: Bottom (B) + Right (R)
    # Directions: 0=Top, 1=Bottom, 2=Left, 3=Right

    # For each direction, what opposite direction is needed?
    # If cell (i,j) has end going Up, cell (i-1,j) must have end going Down
    # If cell (i,j) has end going Down, cell (i+1,j) must have end going Up
    # If cell (i,j) has end going Left, cell (i,j-1) must have end going Right
    # If cell (i,j) has end going Right, cell (i,j+1) must have end going Left

    # Pipe types: (vertical_directions, horizontal_directions)
    # (None means no end in that direction)
    pipe_types = {
        '1': ((1, 0), (0, 1)),  # Top + Left: vertical=T, horizontal=L
        '2': ((0, 1), (1, 0)),  # Top + Right: vertical=T, horizontal=R
        '3': (0, 1),            # Bottom + Left: vertical=B, horizontal=L -> Actually (1,0), (0,1)
        '4': (1, 0),            # Bottom + Right: vertical=B, horizontal=R
    }

    # Let me redo this more clearly:
    # Each pipe has 2 ends, each going in one of 4 directions
    # Type 1: Up, Left -> ends at top and left of the cell
    # Type 2: Up, Right -> ends at top and right of the cell
    # Type 3: Down, Left -> ends at bottom and left of the cell
    # Type 4: Down, Right -> ends at bottom and right of the cell

    # For a pipe to be non-leaking:
    # - If an end points to another cell, that cell must have the complementary end
    # - If an end points to the border, that's valid (it's connected to the border)

    # Complementary directions:
    # Up <-> Down, Left <-> Right

    def get_deep_copy(grid):
        return [row[:] for row in grid]

