                    dirs = [( -1, 0), (0, -1)]   # Up, Left
                elif p == '2':
                    dirs = [(-1, 0), (0, 1)]    # Up, Right
                elif p == '3':
                    dirs = [(1, 0), (0, -1)]    # Down, Left
                elif p == '4':
                    dirs = [(1, 0), (0, 1)]     # Down, Right

                for di, dj in dirs:
                    ni, nj = i + di, j + dj
                    # Check if this direction is within/outside grid
