            parent[x] = find(parent[x])
        return parent[x]

    def try_same(r1, r2):
        if r1 == r2:
            return True

        if assigned[r1] and assigned[r2]:
            if color[r1] != color[r2]:
                return False

        if not assigned[r1] and not assigned[r2]:
            parent[r2] = r1
            return True

        if not assigned[r1]:
            parent[r2] = r1
            assigned[r1] = assigned[r2]
            color[r1] = color[r2]
            assigned[r2] = False
            return True

        if not assigned[r2]:
            parent[r2] = r1
            assigned[r1] = assigned[r2]
            color[r2] = color[r1]
            assigned[r1] = False
            return True

        return False

    def try_diff(r1, r2):
        if r1 == r2:
            if assigned[r1]:
                return False
            else:
                return True

        if assigned[r1] and assigned[r2]:
            if color[r1] == color[r2]:
                return False

        if not assigned[r1] and not assigned[r2]:
            parent[r2] = r1
            assigned[r1] = True
            assigned[r2] = True
            # Force different colors
            if not assigned[r2]:
                color[r2] = (color[r1] + 1) % 2 if color[r1] is not None else 0
            return True

        if not assigned[r1]:
            parent[r2] = r1
            assigned[r1] = True
            assigned[r2] = True
            color[r1] = (color[r2] + 1) % 2 if color[r2] is not None else 0
