import heapq

def solution(a_str, b_str):
    a = list(map(int, a_str.split()))
    b = list(map(int, b_str.split()))
    a.sort()
    b.sort()

    # Check parity invariant - must match
    a_parities = sorted([x % 2 for x in a])
    b_parities = sorted([x % 2 for x in b])
    if a_parities != b_parities:
        return "-1\n"

    # Already at target
    if a == b:
        return "0\n"

    # Heuristic: sum of distances (sorted positions)
    def compute_heuristic(current, target):
        c = sorted(current)
        t = sorted(target)
        return sum(abs(ci - ti) for ci, ti in zip(c, t))

    start_state = tuple(a)
    target_state = tuple(b)

    # A* search: priority = (g + h, g, state, path)
    # g = number of operations so far
    # h = heuristic estimate to target
    # path = list of (from_pos, center_pos) for each operation
    pq = [(compute_heuristic(start_state, target_state), 0, start_state, [])]
    visited = {start_state}

    # Limit to prevent infinite loop (operations within 1000 limit)
    while pq:
        prio, g, state, path = heapq.heappop(pq)

        if state == target_state:
            # Found solution
            result = []
            for from_pos, center_pos in path:
                result.append(f"{from_pos} {center_pos}")
            return f"{len(result)}\n" + "\n".join(result)

        if g >= 1000:
            break

        pos_list = list(state)

        # Try each pair (i, j) where i is stone to move from, j is center
        for i in range(4):
            for j in range(4):
                if i == j:
                    continue

                from_pos = pos_list[i]
                center_pos = pos_list[j]

                # Moving from same position as center gives same position
                if from_pos == center_pos:
                    continue

                new_pos = 2 * center_pos - from_pos
                if abs(new_pos) > 10**18:
                    continue

                new_state_list = list(pos_list)
                new_state_list[i] = new_pos
                new_state_sorted = tuple(sorted(new_state_list))

                if new_state_sorted not in visited:
                    visited.add(new_state_sorted)
                    h = compute_heuristic(new_state_sorted, target_state)
                    new_g = g + 1
                    heapq.heappush(pq, (new_g + h, new_g, new_state_sorted, path + [(from_pos, center_pos)]))

    # No solution found
    return "-1\n"

