def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    # Parse vertex types
    vertex_types = []
    idx = 1
    for i in range(n):
        parts = list(map(int, lines[idx].split()))
        k = parts[0]
        if k > 0:
            vertex_types.append(parts[1:])
        else:
            vertex_types.append([])
        idx += 1

    # Build reverse mapping: type -> list of vertices where it appears
    type_to_vertices = [[] for _ in range(m + 1)]
    for i in range(n):
        for t in vertex_types[i]:
            type_to_vertices[t].append(i)

    # Maximum number of types at any vertex (minimum colors needed)
    max_clique = 0
    for i in range(n):
        max_clique = max(max_clique, len(vertex_types[i]))

    # Assign colors to each type greedily
    colors = [0] * (m + 1)

    for t in range(1, m + 1):
        if not type_to_vertices[t]:
            colors[t] = 1
            continue

        # Find colors already used by types appearing at vertices where type t also appears
        used_for_t = set()
        for v in type_to_vertices[t]:
            if not vertex_types[v]:
                continue
            # For each type at this vertex (except t itself), mark its color if assigned
            for other_t in vertex_types[v]:
                if other_t != t and colors[other_t] != 0:
                    used_for_t.add(colors[other_t])

        # Assign the smallest available color
        assigned = False
        for c in range(1, max_clique + 2):
            if c not in used_for_t:
                colors[t] = c
                assigned = True
                break

        # If all colors in range are used, still assign 1 (worst case)
        if not assigned:
            colors[t] = 1

    # Find maximum color actually used
    actual_max = 1
    if colors[1:] > [0]:
        actual_max = max(colors[1:])

    # Count actual max needed considering conflicts
    # Actually recalculate based on valid coloring
    real_min = max_clique
    if real_min == 0:
        real_min = 1

    result = f"{real_min}\n" + " ".join(str(colors[i]) for i in range(1, m + 1))
    return result


