    n, m = map(int, lines[0].split())
    s = lines[1]
    t = lines[2]

    results = []

    # For each possible substring starting position in S
    for start in range(n - m + 1):
        mapping = {}
        inv_mapping = {}  # Maps characters from T side (as they appear in S)
        valid = True

        for i in range(m):
            s_char = s[start + i]
            t_char = t[i]

            # Get existing mappings
            existing_a_to_b = mapping.get(s_char)
            existing_b_to_a = inv_mapping.get(t_char)

            # Check consistency
            if existing_a_to_b is not None and existing_a_to_b != t_char:
                # s_char was already supposed to map to a different target
                valid = False
                break
            if existing_b_to_a is not None and existing_b_to_a != s_char:
                # t_char was already supposed to map back to a different source
                valid = False
                break

            if valid:
                # Handle the pairing: if different characters, they form a pair
                if s_char != t_char:
                    if s_char not in mapping:
                        mapping[s_char] = t_char
                    if t_char not in inv_mapping:
                        inv_mapping[t_char] = s_char
                else:
                    # Same character, self-mapping (fixed point)
                    # This is always valid, no changes needed

        if valid:
            results.append(start + 1)  # 1-indexed position

    results.sort()
    result_str = str(len(results))
    if results:
        result_str += '\n' + ' '.join(map(str, results))
    return result_str

