    return " ".join(map(str, range(1, n+1))) + "\n" + " ".join(map(str, range(1, m+1))) + "\n"

def check_valid(strings, n, m, row_perm, col_perm):
    """Check if the given row and column permutations avoid string crossings."""
    inv_row = [0] * (n + 2)
    inv_col = [0] * (m + 2)
    for pos, orig in enumerate(row_perm):
        inv_row[orig] = pos + 1
    for pos, orig in enumerate(col_perm):
        inv_col[orig] = pos + 1

    # Group strings by their side connections
    # Check if any pair of strings would cross in the permuted layout

    for i in range(len(strings)):
        for j in range(i+1, len(strings)):
            s1, s2 = strings[i], strings[j]
            if cross_strings(s1, s2, inv_row, inv_col):
                return False
    return True

