    first_line = lines[0].split()
    N, M = int(first_line[0]), int(first_line[1])

    second_line = lines[1].split()
    A = [int(x) for x in second_line]

    # Sort A for deterministic processing
    A.sort()

    # Create a set for quick lookup
    A_set = set(A)
    B_set = set(range(M)) - A_set
    in_A = [False] * M
    for a in A:
        in_A[a] = True

    # Determine if M is small enough for direct computation
    # A reasonable threshold based on the constraints
    MAX_M_FOR_DIRECT = 800000

    if M <= MAX_M_FOR_DIRECT:
        # Direct approach: compute B (already done via B_set)
        # Track which residues are obtainable
        obtainable = [False] * M

        # For each a in A, add all b in B (mod M)
        for a in A:
            for b in range(M):
                if b in B_set:
                    obtainable[(a + b) % M] = True

        # Find unobtainable residues
        unobtainable = []
        for x in range(M):
            if not obtainable[x]:
                unobtainable.append(x)

        # Format output
        result_lines = [str(len(unobtainable))]
        if unobtainable:
            result_lines.append(' '.join(map(str, unobtainable)))
        return '\n'.join(result_lines)
    else:
        # For large M, mark B membership and compute reachability differently
        in_B = [False] * M
        for b in B_set:
            in_B[b] = True

        obtainable = [False] * M

        # For each a in A, mark all obtainable (a + b) mod M
        for a in A:
            for b in B_set:
                obtainable[(a + b) % M] = True

        unobtainable = []
        for x in range(M):
            if not obtainable[x]:
                unobtainable.append(x)

        result_lines = [str(len(unobtainable))]
        if unobtainable:
            result_lines.append(' '.join(map(str, unobtainable)))
        return '\n'.join(result_lines)

def solution(input_str):
    # Parse input
    lines = input_str.strip().split('\n')
    if len(lines) < 3:
        return '0'

    s1, s2, virus = lines[0], lines[1], lines[2]
    n, m, v_len = len(s1), len(s2), len(virus)

    # Handle corner case: if virus is longer than both strings combined, it can't appear
    if v_len > n + m:
        # Fall through - the automaton will never reach state v_len

    # Build KMP prefix function for virus
    pi = [0] * v_len
    for i in range(1, v_len):
        j = pi[i-1]
        while j > 0 and virus[i] != virus[j]:
            j = pi[j-1]
        if virus[i] == virus[j]:
            j += 1
        pi[i] = j

    # Build KMP automaton: automaton[k][c] = next state given current matched prefix length k and char c
    automaton = [[0] * 26 for _ in range(v_len + 1)]

    for k in range(v_len + 1):
        for c in range(26):
            char = chr(ord('A') + c)
            if k == v_len:
                automaton[k][c] = 0  # Can't be in this state during valid transitions
            else:
                j = k
                while j > 0 and virus[j] != char:
                    j = pi[j-1]
                if virus[j] == char:
                    automaton[k][c] = j + 1
                else:
                    automaton[k][c] = 0

    # DP: dp[i][j][k] = max LCS length using s1[:i], s2[:j], virus_prefix matched = k
    NEG_INF = float('-inf')
    dp = [[[NEG_INF] * (v_len + 1) for _ in range(m + 1)] for _ in range(n + 1)]

    # Parent for reconstruction: (i, j, k) stores what move was taken
    parent = [[[None] * (v_len + 1) for _ in range(m + 1)] for _ in range(n + 1)]

    # dp[0][0][0] = 0 (base case - empty subsequences match, no virus matched)
    dp[0][0][0] = 0

    for i in range(n + 1):
        for j in range(m + 1):
            for k in range(v_len + 1):
                if dp[i][j][k] == NEG_INF:
                    continue

                # Try matching s1[i] == s2[j]
                if i < n and j < m and s1[i] == s2[j]:
                    c_idx = ord(s1[i]) - ord('A')
                    next_k = automaton[k][c_idx]
                    # Only allow if it doesn't complete the virus
                    if next_k < v_len:
                        if dp[i][j][k] + 1 > dp[i+1][j+1][next_k]:
                            dp[i+1][j+1][next_k] = dp[i][j][k] + 1
                            parent[i+1][j+1][next_k] = ('match',)

                # Try skipping s1[i]
                if i < n:
                    if dp[i][j][k] > dp[i+1][j][k]:
                        dp[i+1][j][k] = dp[i][j][k]
                        parent[i+1][j][k] = ('skip1',)

                # Try skipping s2[j]
                if j < m:
                    if dp[i][j][k] > dp[i][j+1][k]:
                        dp[i][j+1][k] = dp[i][j][k]
                        parent[i][j+1][k] = ('skip2',)

    # Find the maximum LCS length that doesn't complete virus
    max_len = 0
    best_k = 0
    for k in range(v_len + 1):
        if dp[n][m][k] > max_len:
            max_len = dp[n][m][k]
            best_k = k

    if max_len == 0:
        return '0'

    # Reconstruct the LCS by backtracking through parent pointers
    res = []
    i, j, k = n, m, best_k

    while (i, j, k) != (0, 0, 0):
        p = parent[i][j][k]
        if p is None:
            break

        if p[0] == 'match':
            res.append(s1[i-1])
            i -= 1
            j -= 1
            # Compute the previous k state
            c_idx = ord(s1[i]) - ord('A')
            k = automaton[k][c_idx]
        elif p[0] == 'skip1':
            i -= 1
        elif p[0] == 'skip2':
            j -= 1

    res.reverse()
    return ''.join(res)

