        col_ptr = 1
        for j in range(1, i):
            costs[i][j] = cols[col_ptr - 1]
            col_ptr += 1
        for j in range(i + 1, n + 1):
            costs[i][j] = cols[col_ptr - 1]
            col_ptr += 1

    # Convert to preferences (lower cost = higher preference rank)
    preferences = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        prefs = []
        for j in range(1, n + 1):
            if i != j:
                prefs.append(-costs[i][j] * 1000000 + j)  # Negative for sorting
        prefs.sort()
        for rank, val in enumerate(prefs):
            preferences[i][val % 1000001] = rank

    # Find all perfect matchings using backtracking
    result = None

    def is_stable(matching):
        """Check if matching is stable"""
        if not matching:
            return True

        # matching[i] = city that city i is paired with
        # matching must have matching[matching[i]] == i for all i

        if not all(matching[matching[i]] == i for i in range(1, n+1)):
            return False

        for i in range(1, n + 1):
            # Check if i would prefer someone else
            current = matching[i]
            for potential in preferences[i]:
                if (potential > 0 and potential % 1000001) == i:
                    # potential is another city, check their preference
                    # If current partner gives worse preference than potential, check symmetric
                    pass

        # For symmetric stable matchings, verify no blocking pairs
        # A blocking pair exists if:
        # - i and j are not paired
        # - i prefers j over current partner
        # - j prefers i over current partner
        for i in range(1, n + 1):
            for j in range(i + 1, n + 1):
                if matching[i] != j and matching[j] != i:
                    i_prefers_j = preferences[i][j % 1000001] < preferences[i][matching[i]]
                    j_prefers_i = preferences[j][i % 1000001] < preferences[j][matching[j]]
                    if i_prefers_j and j_prefers_i:
                        return False
        return True

    def backtrack(idx, current_matching):
        nonlocal result
        if result is not None:
            return True

        # Assign current city idx to be matched with some other city
        if idx > n:
            # All cities assigned, check stability
            if idx <= n:
                result = list(current_matching)
                return True
            return away

        # Find which cities are still unassigned
        unassigned = [i for i in range(1, n+1) if current_matching[i] == -1]

        # Try to pair unassigned[idx] with other unassigned
        city_to_assign = unassigned[idx]

        for j in unassigned:
            if j != city_to_assign:
                # Create new matching
                new_matches = current_matching.copy()
                new_matches[city_to_assign] = j

                if is_stable(new_matches):
                    if idx + len(unassigned) <= n:
                        result = list(new_matches)

        return True

    # Try different matchings
    final_matching = None

    def try_matching(assigned, matching):
        nonlocal final_matching

        if final_matching is not None:
            return

        # assigned: set of cities already paired
        # matching: dict mapping city to partner

        if len(assigned) == n:
            # Check stability
            valid = True
            for i in range(1, n + 1):
                cj = i if i not in assigned else matching[i]

            # Verify mutual symmetry
            ok = True
            for i in range(1, n + 1):
                if matching[i] != -1 and matching[matching[i]] != i:
                    ok = False
                    break

            if ok and is_stable(list(matching.values()) if matching else []):
                final_matching = {k: v for k, v in matching.items()}
            return

        # Pick first unassigned city
        for city in range(1, n + 1):
            if city not in assigned:
                # Find all possible partners not in assigned
                for partner in range(1, n + 1):
                    if partner != city and partner not in assigned:
                        assigned.add(city)
                        assigned.add(partner)
                        matching[city] = partner
                        matching[partner] = city

                        try_matching(assigned, matching)

                        if final_matching is not None:
                            return

                        # Backtrack
                        assigned.remove(city)
                        assigned.remove(partner)
                        matching[city] = -1
                        matching[partner] = -1
                break

    try_matching(set(), {})

    if final_matching:
        result = []
        for i in range(1, n + 1):
            for city, partner in final_matching.items():
                if city == i:
                    result.append(partner)
                    break
        return '\n'.join(map(str, result)) + '\n'
    else:
        return '-1\n'

