# Helper function for Union-Find to check if edges form a tree
def is_tree_set(edge_set, n):
    """Check if a set of edges forms a tree on n vertices."""
    parent = list(range(n))
    def find(i):
        if parent[i] != i:
            parent[i] = find(parent[i])
        return parent[i]
    def union(i, j):
        root_i, root_j = find(i), find(j)
        if root_i != root_j:
            parent[root_i] = root_j
            return True
        return False

    for v, u in edge_set:
        if not union(v, u):
            return False  # Can't add more edges (already in same component)

    # Must be connected (all vertices in one component)
    return parent[0] == 0

def solution(input_str: str) -> str:
    lines = input_str.strip().split('\n')
    n = int(lines[0])

    # Read the given tree edges
    edge_set = set()
    for line in lines[1:]:
        v, u = map(int, line.split())
        edge_set.add((min(v, u), max(v, u)))

    # All possible edges in complete graph K_n (0-indexed)
    all_edges = []
    for i in range(n):
        for j in range(i + 1, n):
            all_edges.append((i, j))

    MOD = 1000000007
    result = [0] * n

    # For n <= 12, we can enumerate all possible trees using combinations
    for edges in combinations(all_edges, n - 1):
        edge_tuple_set = set(edges)

        # Check if this set of edges forms a valid tree
        if is_tree_set(edge_tuple_set, n):
            # Count how many edges are shared with the given tree
            shared = sum(1 for e in edge_tuple_set if e in edge_set)
            result[shared] = (result[shared] + 1) % MOD

    return " ".join(map(str, result))


