                        dp[u][k][1] = new_dp_1[k]

    # Find max items within budget
    result = 0
    for k in range(n + 1):
        if dp[0][k][0] <= b:
            result = max(result, k)
        if dp[0][k][1] <= b:
            result = max(result, k)

    return str(result)

