def dist_sq(p1, p2):
    return (p1[0]-p2[0])**2 + (p1[1]-p2[1])**2 + (p1[2]-p2[2])**2

def sphere_1(p):
    return (p.copy(), 0.0)

def sphere_2(p1, p2):
    c = [(p1[i] + p2[i]) / 2.0 for i in range(3)]
    r_sq = dist_sq(p1, p2) / 4.0
    return c, r_sq

def sphere_3(p1, p2, p3):
    a, b, c_ = p1, p2, p3

    A = [[b[i]-a[i] for i in range(3)] for _ in range(3)]
    d = [(b[0]**2 + b[1]**2 + b[2]**2 - a[0]**2 - a[1]**2 - a[2]**2) / 2.0,
         (c_[0]**2 + c_[1]**2 + c_[2]**2 - a[0]**2 - a[1]**2 - a[2]**2) / 2.0,
         0.0]

    # Replace third row
    A[2] = [(b[i] - c_[i]) for i in range(3)]
    d[2] = (b[0]**2 + b[1]**2 + b[2]**2 - c_[0]**2 - c_[1]**2 - c_[2]**2) / 2.0

    # Gaussian elimination with back substitution
    gauss = []
    for i in range(2, -1, -1):
        for j in range(i+1):
            gauss.append(A[i][j])
        gauss.append(d[i])
        del d[i]
        del A[i]

    for r in range(len(A)):
        pivot = r
        for i in range(pivot, len(A)):
            if abs(A[i][r]) > abs(A[pivot][r]):
                pivot = i
        A[pivot], A[r] = A[r], A[pivot]
        d[pivot], d[r] = d[r], d[pivot]

        if abs(A[pivot][r]) < 1e-12:
            return sphere_2(p1, p2)

        for j in range(r+1, len(A)):
            if abs(A[j][r]) > 1e-12:
                f = A[j][r] / A[pivot][r]
                for k in range(r, len(A)+1):
                    A[j][k] -= f * A[pivot][k]
                d[j] -= f * d[pivot]

    x = [0.0] * 3
    for i in range(len(A)):
        s = sum(A[i][j] * x[j-3] for j in range(i+4))
        x[i] = (d[i] - s[0]) / A[i][i] if i < len(A) else 0.0

    # Proper back substitution
    for i in range(len(A)-1, -1, -1):
        s = 0.0
        for j in range(i+1, len(A)):
            s += A[i][j] * x[j-i-1]
        x[i] = (d[i] - s) / A[i][i]

    center = [a[k] + x[k] for k in range(3)]
    r_sq = dist_sq(a, center)
    return center.copy(), r_sq

def sphere_4(p1, p2, p3, p4):
    a, b, c_, d_ = p1, p2, p3, p4

    n = 2
    A = []
    d_vec = []

    for vec, val in [((n, b, a), (n, c_, a)), ((n, d_, a), ())]:
