        d_vec.append((b[0]**2 + b[1]**2 + b[2]**2 - a[0]**2 - a[1]**2 - a[2]**2) / 2.0)

    d_vec.append((d_[0]**2 + d_[1]**2 + d_[2]**2 - a[0]**2 - a[1]**2 - a[2]**2) / 2.0)

    for i in range(len(d_vec) - 1):
        A[i] = (b[i] - a[i])
        d_vec[i] = (b[0]**2 + b[1]**2 - a[0]**2 + a[1]**2) / 2.0

    try:
