        if gauss is None:
            return sphere_2(p1, p2)

        center = [a[k] + gauss[k] for k in range(3)]
        r_sq = dist_sq(a, center)

        if dist_sq(b, center) > r_sq * 1.01 or dist_sq(c_, center) > r_sq * 1.01 or dist_sq(d_, center) > r_sq * 1.01:
            return sphere_2(p1, p2)

        return center, r_sq
    except:
        return sphere_2(p1, p2)

def gaussian_solve(A, b):
    n = len(A)
    M = [row[:] + [b[i]] for i, row in enumerate(A)]

    for col in range(n):
        max_row = col
        for row in range(col + 1, n):
            if abs(M[row][col]) > abs(M[max_row][col]):
                max_row = row
        M[col], M[max_row] = M[max_row], M[col]

        if abs(M[col][col]) < 1e-12:
            return None

        for row in range(col + 1, n):
            if abs(M[row][col]) > 1e-12:
                factor = M[row][col] / M[col][col]
                for k in range(col, n + 1):
                    M[row][k] -= factor * M[col][k]

    x = [0.0] * n
    for row in range(n - 1, -1, -1):
        x[row] = M[row][n]
        for col in range(row + 1, n):
            x[row] -= M[row][col] * x[col]
        x[row] /= M[row][row]

    return x.copy()

def welzl(points):
    points = points[:]
    random.shuffle(points)
    boundary = []

    def rec(pts, boundary):
        if len(pts) == 0:
            if len(boundary) == 0:
                pts[0][0] = 0.0
                pts[0][1] = 0.0
                pts[0][2] = 0.0
                return (pts[0].copy(), 0.0)
            elif len(boundary) == 1:
                b = boundary[0]
                return b.copy(), 0.0
            elif len(boundary) == 2:
                return sphere_2(boundary[0].copy(), boundary[1].copy())
            elif len(boundary) == 3:
                return sphere_3(boundary[0].copy(), boundary[1].copy(), boundary[2].copy())
            return None

        if len(boundary) == 4:
            p = pts[0].copy()
            return sphere_4(p, *boundary)

        p = pts[0].copy()
        r, s = rec(pts[1:], boundary)

        if dist_sq(p, s) > r:
            boundary.append(p.copy())
            r, s = rec(pts[1:], boundary)
            boundary.pop()

        return s

    return rec(points, [])

