                                if (nx, ny) not in visited:
                                    visited.add((nx, ny))
                                    queue.append((nx, ny, path + [dir_char]))
                elif lr_swap and not ud_swap:
                    for dir_char, (dx, dy) in [('L', (0, 1)), ('R', (0, -1)), ('D', (1, 0)), ('U', (-1, 0))]:
                        nx, ny = curr_x + dx, curr_y + dy
                        if 0 <= nx < n and 0 <= ny < m:
                            if grid[curr_x][curr_y] != '*':
                                if (nx, ny) not in visited:
                                    visited.add((nx, ny))
                                    queue.append((nx, ny, path + [dir_char]))
                elif not lr_swap and ud_swap:
                    for dir_char, (dx, dy) in [('R', (0, 1)), ('L', (0, -1)), ('U', (1, 0)), ('D', (-1, 0))]:
                        nx, ny = curr_x + dx, curr_y + dy
                        if 0 <= nx < n and 0 <= ny < m:
                            if grid[curr_x][curr_y] != '*':
                                if (nx, ny) not in visited:
                                    visited.add((nx, ny))
                                    queue.append((nx, ny, path + [dir_char]))
                else:  # both swapped
                    for dir_char, (dx, dy) in [('L', (0, 1)), ('R', (0, -1)), ('U', (1, 0)), ('D', (-1, 0))]:
                        nx, ny = curr_x + dx, curr_y + dy
                        if 0 <= nx < n and 0 <= ny < m:
                            if grid[curr_x][curr_y] != '*':
                                if (nx, ny) not in visited:
                                    visited.add((nx, ny))
                                    queue.append((nx, ny, path + [dir_char]))

            return ""  # No path found with this swap config

    # Since we don't know swap status, let's try all 4 and see which works
    swap_configs = [(False, False), (True, False), (False, True), (True, True)]

    for lr_swap, ud_swap in swap_configs:
        path = solve_with_swap(lr_swap, ud_swap)
        if path:
            return path

    return ""

def solution(s):
    n = int(s.strip())
    if n == 0:
        return "0"
    MOD = 10**9 + 7
    return str(pow(3, n - 1, MOD))

def solution(input_str):
    part = input_str.strip().split()
    if len(part) < 4:
        return "Happy new year!\n"

    k, x, n, m = int(part[0]), int(part[1]), int(part[2]), int(part[3])

    def count_ac(s):
        if not s:
            return 0
        return s.count('AC')

    def generate_strings(length):
        """Generate up to 2^length strings of A's and C's, limited for performance"""
        if length > 17:
            # For large length, generate only a subset of strings
            return [
                'A' * length,
                'C' * length,
                'A' + 'C' * (length - 1),
                'C' + 'A' * (length - 1),
                'CAC' * (length // 3) + 'A' * (length % 3),
                'ACA' * (length // 3) + 'A' * (length % 3)
            ]
        strings = []
        for i in range(2 ** length):
            s = []
            for j in range(length):
                # bit j, if 1 append 'C', else 'A'
                if (i >> j) & 1:
                    s.append('C')
                else:
                    s.append('A')
            strings.append(''.join(s))
        return strings

    s1_list = generate_strings(n)
    s2_list = generate_strings(m)

    # Recursively build sk from s1 and s2
    def build_sk(k):
        if k == 1:
            return s1
        if k == 2:
            return s2
        return build_sk(k - 2) + build_sk(k - 1)

    for s1 in s1_list:
        for s2 in s2_list:
            sk = build_sk(k)
            if count_ac(sk) == x:
                return f"{s1}\n{s2}\n"

    return "Happy new year!\n"
